-- Seed for Shape, generated from ReferenceData/shapes.txt (Metra GTFS static).
-- Re-running replaces every row, so apply this BEFORE Run is populated:
-- Run.ShapeKey references Shape.ShapeId and ShapeIds are assigned here by
-- StaticShapeId sort order, which is not stable across feed publishes.
--
-- PolyLine     Google encoded polyline, precision 5, points in
--              shape_pt_sequence order. The source sequence numbers are
--              non-contiguous (2, 4, 6, ...) so they are sorted, not indexed.
--              Precision 5 caps positional error at ~1.1 m, well inside the
--              tolerance for snap-to-shape.
-- PointCount   points in PolyLine; verified by decoding it back.
-- LengthMeters cumulative great-circle length over the DECODED points, so it
--              matches the geometry a consumer actually reads.

DELETE FROM Shape;

